/* kalloc(): remove one free page */
acquire(&kmem.lock);
r = kmem.freelist;
if (r) kmem.freelist = r->next;
release(&kmem.lock);

/* kfree(): add one free page */
acquire(&kmem.lock);
r->next = kmem.freelist;
kmem.freelist = r;
release(&kmem.lock);

volatile uchar *memory = (volatile uchar *)allocation;
for (int offset = 0; offset < bytes; offset++)
  memory[offset] = tag;

